import { TestBed } from '@angular/core/testing';
import { ActivityHealthReport } from '../../../core/models';
import { BEACON_HOME_SECURITY, buildReport, withRange, withoutEnoughHistory } from '../../../../testing/activity-health-fixtures';
import { collapsedText } from '../../../../testing/dom-queries';
import { AccountSummary } from './account-summary';

async function renderSummary(report: ActivityHealthReport): Promise<string> {
  TestBed.configureTestingModule({ imports: [AccountSummary] });
  const fixture = TestBed.createComponent(AccountSummary);
  fixture.componentRef.setInput('report', report);
  await fixture.whenStable();
  return collapsedText(fixture.nativeElement as HTMLElement);
}

describe('AccountSummary', () => {
  it('shows "{count} {noun} · usually {low}–{high} a week" with the status label, taking low and high as given', async () => {
    const report = buildReport({ account: BEACON_HOME_SECURITY, weekStart: '2026-07-20', summary: withRange(10, 27, 18, 38, 'below', -3.5), locations: [] });

    const summaryText = await renderSummary(report);

    expect(summaryText).toContain('10 inbound events · usually 18–38 a week');
    expect(summaryText).toContain('▼ Lower than usual');
  });

  it('shows the count with no range and weeks needed from the report minimumEligibleWeeks when history is insufficient', async () => {
    const report = {
      ...buildReport({ account: BEACON_HOME_SECURITY, weekStart: '2026-07-20', eventType: 'call_received', summary: withoutEnoughHistory(5, 2), locations: [] }),
      minimumEligibleWeeks: 6,
    };

    const summaryText = await renderSummary(report);

    expect(summaryText).toContain('5 calls');
    expect(summaryText).not.toContain('5 calls ·');
    expect(summaryText).not.toMatch(/usually \d+–\d+ a week/);
    expect(summaryText).toContain('Not enough history yet (2 of 6 weeks needed)');
  });
});
import { TestBed } from '@angular/core/testing';
import { WeekRange } from '../../../core/models';
import { LATEST_COMPLETE_WEEK, seedAccounts, sundayOf } from '../../../../testing/activity-health-fixtures';
import { findButton, getButton, getSelect, isDisabled, optionTexts } from '../../../../testing/dom-queries';
import { DashboardFilters } from './dashboard-filters';

const PREVIOUS_WEEK = '◀ Previous week';
const NEXT_WEEK = 'Next week ▶';

interface WeekInputs {
  week?: WeekRange | null;
  earliestWeek?: string | null;
  latestCompleteWeek?: string | null;
}

interface FiltersUnderTest {
  root: HTMLElement;
  selectedWeeks: string[];
}

async function renderFilters(weekInputs: WeekInputs): Promise<FiltersUnderTest> {
  TestBed.configureTestingModule({ imports: [DashboardFilters] });
  const fixture = TestBed.createComponent(DashboardFilters);
  fixture.componentRef.setInput('accounts', seedAccounts());
  fixture.componentRef.setInput('accountId', 14);
  fixture.componentRef.setInput('eventType', 'all');
  Object.entries(weekInputs).forEach(([inputName, value]) => fixture.componentRef.setInput(inputName, value));
  const selectedWeeks: string[] = [];
  fixture.componentInstance.weekSelected.subscribe((week) => selectedWeeks.push(week));
  await fixture.whenStable();
  return { root: fixture.nativeElement as HTMLElement, selectedWeeks };
}

function weekInputsAt(weekStart: string, earliestWeek = '2026-01-26'): WeekInputs {
  return { week: { start: weekStart, end: sundayOf(weekStart) }, earliestWeek, latestCompleteWeek: LATEST_COMPLETE_WEEK };
}

describe('DashboardFilters', () => {
  it('lists every account by its plain name under "Viewing as"', async () => {
    const { root } = await renderFilters(weekInputsAt('2026-07-20'));

    expect(optionTexts(getSelect(root, 'Viewing as'))).toEqual(seedAccounts().map((account) => account.name));
  });

  it('offers All activity, Calls, Leads, Appointments under "Activity type"', async () => {
    const { root } = await renderFilters(weekInputsAt('2026-07-20'));

    expect(optionTexts(getSelect(root, 'Activity type'))).toEqual(['All activity', 'Calls', 'Leads', 'Appointments']);
  });

  it.each([
    { position: 'at latestCompleteWeek', weekStart: '2026-07-20', earliestWeek: '2026-01-26', previousDisabled: false, nextDisabled: true },
    { position: 'at earliestWeek', weekStart: '2026-01-26', earliestWeek: '2026-01-26', previousDisabled: true, nextDisabled: false },
    { position: 'between the bounds', weekStart: '2026-03-02', earliestWeek: '2026-01-26', previousDisabled: false, nextDisabled: false },
    { position: 'where earliestWeek equals latestCompleteWeek', weekStart: '2026-07-20', earliestWeek: '2026-07-20', previousDisabled: true, nextDisabled: true },
  ])('bounds the week stepper $position', async ({ weekStart, earliestWeek, previousDisabled, nextDisabled }) => {
    const { root } = await renderFilters(weekInputsAt(weekStart, earliestWeek));

    expect(isDisabled(getButton(root, PREVIOUS_WEEK))).toBe(previousDisabled);
    expect(isDisabled(getButton(root, NEXT_WEEK))).toBe(nextDisabled);
  });

  it.each([
    { button: PREVIOUS_WEEK, weekStart: '2026-07-20', expectedWeek: '2026-07-13' },
    { button: NEXT_WEEK, weekStart: '2026-07-13', expectedWeek: '2026-07-20' },
  ])('"$button" from $weekStart emits weekSelected $expectedWeek', async ({ button, weekStart, expectedWeek }) => {
    const { root, selectedWeeks } = await renderFilters(weekInputsAt(weekStart));

    getButton(root, button).click();

    expect(selectedWeeks).toEqual([expectedWeek]);
  });

  it.each<{ missing: string; weekInputs: WeekInputs; stepperShown: boolean }>([
    { missing: 'every week input', weekInputs: {}, stepperShown: false },
    { missing: 'week', weekInputs: { ...weekInputsAt('2026-07-20'), week: null }, stepperShown: false },
    { missing: 'earliestWeek', weekInputs: { ...weekInputsAt('2026-07-20'), earliestWeek: null }, stepperShown: false },
    { missing: 'latestCompleteWeek', weekInputs: { ...weekInputsAt('2026-07-20'), latestCompleteWeek: null }, stepperShown: false },
    { missing: 'nothing', weekInputs: weekInputsAt('2026-07-20'), stepperShown: true },
  ])('with $missing unset, shows the week stepper only when all week inputs are set, and both selects always (UI-44)', async ({ weekInputs, stepperShown }) => {
    const { root } = await renderFilters(weekInputs);

    expect(findButton(root, PREVIOUS_WEEK) !== null).toBe(stepperShown);
    expect(findButton(root, NEXT_WEEK) !== null).toBe(stepperShown);
    expect(getSelect(root, 'Viewing as').disabled).toBe(false);
    expect(getSelect(root, 'Activity type').disabled).toBe(false);
  });
});
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { LocationHealth } from '../../../core/models';
import {
  beaconMixedHistoryReport,
  beaconNoEligibleWeeksReport,
  locationRow,
  withRange,
  withoutEnoughHistory,
} from '../../../../testing/activity-health-fixtures';
import { cellTexts, collapsedText, columnHeaderTexts, locationRows } from '../../../../testing/dom-queries';
import { LocationTable } from './location-table';

async function renderTable(locations: LocationHealth[], minimumEligibleWeeks = 4): Promise<HTMLElement> {
  TestBed.configureTestingModule({ imports: [LocationTable] });
  const fixture: ComponentFixture<LocationTable> = TestBed.createComponent(LocationTable);
  fixture.componentRef.setInput('locations', locations);
  fixture.componentRef.setInput('minimumEligibleWeeks', minimumEligibleWeeks);
  await fixture.whenStable();
  return fixture.nativeElement as HTMLElement;
}

function rowFor(root: HTMLElement, location: string): HTMLElement {
  const row = locationRows(root).find((candidate) => cellTexts(candidate).includes(location));
  if (!row) {
    throw new Error(`No row for ${location} in: ${collapsedText(root)}`);
  }
  return row;
}

function usualRangeCellText(root: HTMLElement, location: string): string {
  const usualRangeColumn = columnHeaderTexts(root).indexOf('Usual range');
  expect(usualRangeColumn).toBeGreaterThanOrEqual(0);
  return cellTexts(rowFor(root, location))[usualRangeColumn];
}

describe('LocationTable', () => {
  it('shows the column headers Location, Events, Usual range, Status', async () => {
    const root = await renderTable([locationRow('Site A', withRange(7, 7, 5, 17, 'normal', 0))]);

    expect(columnHeaderTexts(root)).toEqual(['Location', 'Events', 'Usual range', 'Status']);
  });

  it('renders rows in exactly the payload order C, A, D, B and prints low/high as given (UI-41)', async () => {
    const root = await renderTable([
      locationRow('Site C', withRange(7, 7.5, 7, 8, 'normal', 0.1)),
      locationRow('Site A', withRange(2, 7.5, 7, 8, 'below', -2.5)),
      locationRow('Site D', withRange(7, 7.5, 7, 8, 'normal', -1.0)),
      locationRow('Site B', withRange(12, 7.5, 7, 8, 'above', 3.0)),
    ]);

    const renderedLocations = locationRows(root).map((row) => cellTexts(row).find((cell) => /^Site [A-Z]$/.test(cell)));
    expect(renderedLocations).toEqual(['Site C', 'Site A', 'Site D', 'Site B']);
    locationRows(root).forEach((row) => expect(collapsedText(row)).toContain('Usually 7–8 a week'));
  });

  it('labels every status with symbol and text, taking weeks needed from minimumEligibleWeeks (UI-05)', async () => {
    const root = await renderTable(
      [
        locationRow('Site A', withRange(20, 6, 2, 12, 'above', 3.1)),
        locationRow('Site B', withRange(0, 7, 3, 13, 'below', -3.0)),
        locationRow('Site C', withRange(6, 6, 2, 12, 'normal', 0)),
        locationRow('Site D', withoutEnoughHistory(0, 2)),
      ],
      6,
    );

    expect(collapsedText(rowFor(root, 'Site A'))).toContain('▲ Higher than usual');
    expect(collapsedText(rowFor(root, 'Site B'))).toContain('▼ Lower than usual');
    expect(collapsedText(rowFor(root, 'Site C'))).toContain('Within usual range');
    expect(collapsedText(rowFor(root, 'Site D'))).toContain('Not enough history yet (2 of 6 weeks needed)');
  });

  it('leaves the "Usual range" cell empty for every insufficient row while showing its count and message (UI-45, account 14, 2026-02-02)', async () => {
    const root = await renderTable(beaconNoEligibleWeeksReport().locations);
    const expectedCounts: Record<string, string> = { 'Site A': '9', 'Site B': '5', 'Site C': '7', 'Site D': '6' };

    Object.entries(expectedCounts).forEach(([location, count]) => {
      expect(usualRangeCellText(root, location)).toBe('');
      expect(cellTexts(rowFor(root, location))).toContain(count);
      expect(collapsedText(rowFor(root, location))).toContain('Not enough history yet (0 of 4 weeks needed)');
    });
    expect(collapsedText(root)).not.toContain('Usually');
    expect(collapsedText(root)).not.toContain('0–0');
    locationRows(root).forEach((row) => expect(cellTexts(row).filter((cell) => /^[—–-]$/.test(cell))).toEqual([]));
  });

  it('empties the range only for insufficient rows in a mixed table (UI-45, account 14, 2026-03-02)', async () => {
    const root = await renderTable(beaconMixedHistoryReport().locations);

    expect(usualRangeCellText(root, 'Site A')).toBe('');
    expect(usualRangeCellText(root, 'Site C')).toBe('');
    expect(usualRangeCellText(root, 'Site D')).toBe('Usually 2–11 a week');
    expect(usualRangeCellText(root, 'Site B')).toBe('Usually 2–10 a week');
  });
});
